// engine/checkouts.js
// Checkout suggestions.
//   - Double out with three darts in hand uses the curated table below (standard pro routes).
//   - Everything else (fewer darts left mid-visit, straight out, not yet checked in)
//     is generated by searching every route and picking the most sensible one.

