export const CHECKOUT_TABLE = Object.freeze(
  Object.fromEntries(Object.entries(TABLE).map(([k, v]) => [Number(k), v.split(" ").map(parseDart)]))
);

// ---------------------------------------------------------------------------
// Route generator
// ---------------------------------------------------------------------------
// Lower cost = better. Fewest darts wins unless an extra dart buys a far nicer
// double (e.g. 50 with two darts: "10, D20" rather than going for the bull).

const EXTRA_DART_COST = 1.5;
const DOUBLE_PREFERENCE = { 20: 0, 16: 0.05, 18: 0.4, 8: 0.5, 10: 0.6, 12: 0.6, 14: 0.9, 4: 1, 6: 1, 2: 1.4 };

function setupCost(d) {
  if (d.seg === 25) return d.mult === 2 ? 3.2 : 2.6;
  if (d.mult === 1) return 0.2; // every single is the same size, so no preference
  if (d.mult === 3) return 1 + (20 - d.seg) * 0.03; // you're aiming at T20 anyway
  return 3; // using a double to set up is a last resort
}

function finishCost(d, checkOut) {
  if (checkOut === CHECK_OUT.STRAIGHT) {
    if (d.seg === 25) return d.mult === 2 ? 2.4 : 1.8;
    if (d.mult === 1) return 0.2 + (20 - d.seg) * 0.005;
    if (d.mult === 3) return 1 + (20 - d.seg) * 0.03;
    return 1.2 + (20 - d.seg) * 0.02;
  }
  if (d.seg === 25) return 2.5;
  return DOUBLE_PREFERENCE[d.seg] ?? 1.6 + (20 - d.seg) * 0.02;
}

function finishers(checkOut) {
  return checkOut === CHECK_OUT.STRAIGHT ? SCORING_DARTS : SCORING_DARTS.filter((d) => d.mult === 2);
}

const routeMemo = new Map();

function generateRoute(remaining, checkOut, dartsLeft, needsDoubleIn) {
  const key = `${remaining}|${checkOut}|${dartsLeft}|${needsDoubleIn ? 1 : 0}`;
  if (routeMemo.has(key)) return routeMemo.get(key);

  const minDarts = minDartsToFinish(remaining, checkOut, needsDoubleIn);
  let best = null;
  let bestCost = Infinity;
  const fin = finishers(checkOut);
  const setups = SCORING_DARTS;

  const consider = (route) => {
    let cost = (route.length - minDarts) * EXTRA_DART_COST;
    for (let i = 0; i < route.length - 1; i++) cost += setupCost(route[i]);
    cost += finishCost(route[route.length - 1], checkOut);
    if (cost < bestCost) {
      bestCost = cost;
      best = route;
    }
  };

  const firstOk = (d) => !needsDoubleIn || d.mult === 2;
  const stillAlive = (rem) => rem > 0 && !isBustRemaining(rem, checkOut);

  for (let k = minDarts; k <= dartsLeft; k++) {
    if (k === 1) {
      for (const f of fin) if (f.value === remaining && firstOk(f)) consider([f]);
    } else if (k === 2) {
      for (const a of setups) {
        if (!firstOk(a) || !stillAlive(remaining - a.value)) continue;
        for (const f of fin) if (a.value + f.value === remaining) consider([a, f]);
      }
    } else if (k === 3) {
      for (const a of setups) {
        if (!firstOk(a) || !stillAlive(remaining - a.value)) continue;
        for (const b of setups) {
          const left = remaining - a.value - b.value;
          if (!stillAlive(left)) continue;
          for (const f of fin) if (f.value === left) consider([a, b, f]);
        }
      }
    }
  }

  routeMemo.set(key, best);
  return best;
}

// The suggested route as an array of darts, or null if there's no finish on.
export function suggestCheckout(remaining, { checkOut = CHECK_OUT.DOUBLE, dartsLeft = 3, checkedIn = true } = {}) {
  const r = Number(remaining);
  if (!Number.isInteger(r) || r < 1 || dartsLeft < 1) return null;
  const needsDoubleIn = !checkedIn;
  if (minDartsToFinish(r, checkOut, needsDoubleIn) > dartsLeft) return null;

  if (checkOut === CHECK_OUT.DOUBLE && !needsDoubleIn) {
    const fromTable = CHECKOUT_TABLE[r];
    if (fromTable && fromTable.length <= dartsLeft) return fromTable;
  }
  return generateRoute(r, checkOut, dartsLeft, needsDoubleIn);
}

export function routeLabels(route) {
  return route ? route.map(dartLabel) : [];
}
